// ============================================================
// HIER TRAGEN DIE TEILNEHMER IHRE ZUGANGSDATEN EIN.
// Nur Zeilen ändern, die mit "HIER_EINTRAGEN" beginnen.
// Nicht benötigte Credentials einfach so lassen: sie werden übersprungen.
// ============================================================
const credentials = [
  { name: 'Workshop – Google Gemini', type: 'googlePalmApi',
    data: { host: 'https://generativelanguage.googleapis.com', apiKey: 'HIER_EINTRAGEN' } },
  { name: 'Workshop – OpenAI', type: 'openAiApi',
    data: { apiKey: 'HIER_EINTRAGEN' } },
  { name: 'Workshop – Qdrant', type: 'qdrantApi',
    data: { qdrantUrl: 'HIER_EINTRAGEN', apiKey: 'HIER_EINTRAGEN' } },
  { name: 'Workshop – Airtable', type: 'airtableTokenApi',
    data: { accessToken: 'HIER_EINTRAGEN' } },
  { name: 'Workshop – GitHub', type: 'githubApi',
    data: { server: 'https://api.github.com', user: 'HIER_EINTRAGEN', accessToken: 'HIER_EINTRAGEN' } },
  { name: 'Workshop – Ollama', type: 'ollamaApi',
    data: { baseUrl: 'http://localhost:11434' } },
];

// Nur vollständig ausgefüllte Einträge weitergeben
return credentials
  .filter(c => !Object.values(c.data).some(v => String(v).startsWith('HIER_EINTRAGEN')))
  .map(c => ({ json: c }));

// Ergebnis ohne Secrets
return $input.all().map(i => ({ json: {
  status: i.json.id ? 'angelegt' : 'FEHLER',
  id: i.json.id,
  name: i.json.name,
  type: i.json.type,
  fehler: i.json.error?.message
}}));
